import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
with open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl') as f:
    full_content = f.read()

inp_marker = 'Demo pair 1 input (20x20):'
inp_idx = full_content.find(inp_marker)
inp_text = full_content[inp_idx:].replace('\\n', '\n')
inp_lines = inp_text.strip().split('\n')

def to_grid(lines):
    grid = []
    for line in lines:
        vals = line.strip().split()
        if len(vals) == 20:
            grid.append([int(x) for x in vals])
    return grid

inp_grid = to_grid(inp_lines[:20])

# Find 2x2 blocks of same value (not 0) in input
def find_2x2_same_blocks(grid):
    blocks = []
    for r in range(18):
        for c in range(18):
            val = grid[r][c]
            if val != 0 and val == grid[r][c+1] == grid[r+1][c] == grid[r+1][c+1]:
                blocks.append((r, c, val))
    return blocks

same_blocks = find_2x2_same_blocks(inp_grid)
print(f"2x2 blocks of same non-zero value in input: {same_blocks}")

# Find ANY 2x2 blocks (including zeros)
def find_all_2x2_blocks(grid):
    blocks = []
    for r in range(18):
        for c in range(18):
            blocks.append((r, c, grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]))
    return blocks

# Just print 2x2 blocks in rows 4-8, cols 4-10 where there might be structure
print("\n2x2 blocks around rows 6-7, cols 8-9:")
for r in range(4, 10):
    for c in range(6, 12):
        sub = list(zip(*inp_grid[r:r+2][c:c+2]))
        print(f"  ({r},{c}): {sub}")

